import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { getSettingInt } from "@/lib/settings";
import { AutoRefresh } from "@/components/AutoRefresh";
import { PortalHero } from "@/components/portal/PortalHero";
import { Volumes, type VolumeRow, type ServerOption } from "@/components/customer/Volumes";

export const dynamic = "force-dynamic";

export default async function VolumesPage() {
  const user = await requireUser();

  const [volumes, servers, perGbCents] = await Promise.all([
    db.volume.findMany({
      where: { userId: user.id },
      include: { server: true },
      orderBy: { createdAt: "desc" },
    }),
    db.server.findMany({
      where: { userId: user.id, status: "RUNNING" },
      orderBy: { createdAt: "desc" },
    }),
    getSettingInt("volume_price_cents_per_gb", 10),
  ]);

  const rows: VolumeRow[] = volumes.map((v) => ({
    id: v.id,
    name: v.name,
    sizeGB: v.sizeGB,
    priceCents: v.priceCents,
    status: v.status,
    serverId: v.serverId,
    serverName: v.server ? v.server.hostname : null,
  }));

  const serverOptions: ServerOption[] = servers.map((s) => ({
    id: s.id,
    hostname: s.hostname,
  }));

  const transitional = volumes.some((v) => ["PENDING", "DELETING"].includes(v.status));

  return (
    <div className="space-y-6">
      {transitional && <AutoRefresh />}
      <PortalHero
        variant="volumes"
        title="Block Storage"
        sub="Add-on volumes you can attach to any of your running servers."
      />

