import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { getSetting, getSettingBool } from "@/lib/settings";
import { listNxcloudInstances } from "@/lib/actions-nxcloud";
import { annualDiscountPct } from "@/lib/annual-discount";
import { NXCLOUD_DEFAULT_ZONE } from "@/lib/nxcloud";
import { NxcloudClient } from "@/components/customer/NxcloudClient";
import { PortalHero } from "@/components/portal/PortalHero";

export const dynamic = "force-dynamic";

export default async function NxcloudPage() {
  await requireUser();
  const [plans, instances, zone, orderingEnabled, annualPct] = await Promise.all([
    db.nxCloudPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    listNxcloudInstances(),
    getSetting("nxcloud_zone", NXCLOUD_DEFAULT_ZONE),
    getSettingBool("nxcloud_ordering_enabled", false),
    annualDiscountPct(),
  ]);
  const planViews = plans.map((p) => ({
    id: p.id,
    slug: p.slug,
    name: p.name,
    priceCents: p.priceCents,
    storageGB: p.storageGB,
    ramMB: p.ramMB,
    vcpu: p.vcpu,
    collabora: p.collabora,
    talk: p.talk,
    featured: p.featured,
    tagline: p.tagline,
  }));
  return (
    <>
      <PortalHero variant="nxcloud" title="NxCloud" sub="Your private cloud drives and instances — spin up storage in seconds." />
      <NxcloudClient
        plans={planViews}
        instances={instances}
        zone={(zone || NXCLOUD_DEFAULT_ZONE).trim()}
        orderingEnabled={orderingEnabled}
        annualDiscountPct={annualPct}
      />
    </>
  );
}

