/* Shared theme-aware helpers for the account-page aurora canvases.
 *
 * Every ribbon backdrop in this family (StreamsBg, ActivityAurora,
 * BillingAurora, DomainsAurora, MailAurora, PartnerAurora, ServicesAurora,
 * SettingsAurora, SslAurora, SupportAurora, TeamAurora, ToolsAurora,
 * WhatsNewAurora) draws the same way: a linear-gradient stroke, three passes
 * (a blurred halo, a soft body, a hard core), composited with
 * `globalCompositeOperation = "lighter"` so overlapping ribbons bloom into
 * brighter light. That composite mode can only ever ADD light on top of
 * whatever is already there — over the near-black page these were designed
 * for that reads as glowing colour, but over a white/light page it
 * mathematically cannot produce colour: every stroke just pushes the pixels
 * under it toward white, which is the flat grey wash the user reported.
 *
 * The fix is not a different blend mode retune, it's a branch: dark keeps
 * "lighter" and every existing hsla lightness value untouched (so dark mode
 * is pixel-for-pixel the same as before this file existed); light switches
 * to normal "source-over" blending (so a stroke actually PAINTS colour onto
 * the page instead of only ever brightening it) and lowers each stop's
 * lightness by ~28 points — the same hue at ~35-50% L instead of ~62-80% L
 * reads as genuinely saturated colour against white rather than a near-white
 * tint — with alpha bumped up somewhat since normal blending does not stack
 * brightness across overlapping strokes the way additive does.
 *
 * Checked once per animation frame (`isLightTheme()` is a single attribute
 * read) rather than watched with a MutationObserver — these already run a
 * rAF loop, so the cost of checking is nothing next to the drawing itself,
 * and it means flipping the theme toggle repaints the very next frame.
 */

export function isLightTheme(): boolean {
  if (typeof document === "undefined") return false;
  return document.documentElement.getAttribute("data-theme") === "light";
}

/** Dark keeps the additive bloom; light needs real paint on the page. */
export function auroraComposite(isLight: boolean): GlobalCompositeOperation {
  return isLight ? "source-over" : "lighter";
}

/** Same ribbon shape both files' `strand()` functions already build a
 *  gradient from — {hue: [number, number], alpha: number}. */
type StrandLike = { hue: [number, number]; alpha: number };

/**
 * Builds the strand's linear gradient, branching lightness/alpha by theme.
 * Passing `isLight: false` reproduces the original expression exactly —
 * dark mode's output is unchanged.
 */
export function auroraStrandGradient(
  ctx: CanvasRenderingContext2D,
  r: StrandLike,
  w: number,
  isLight: boolean,
): CanvasGradient {
  const grad = ctx.createLinearGradient(0, 0, w, 0);
  const a = isLight ? Math.min(1, r.alpha * 1.7) : r.alpha;
  const endL = isLight ? 34 : 62;
  const midL0 = isLight ? (r.alpha > 0.55 ? 50 : 36) : (r.alpha > 0.55 ? 78 : 64);
  const midL1 = isLight ? (r.alpha > 0.55 ? 52 : 38) : (r.alpha > 0.55 ? 80 : 66);
  grad.addColorStop(0, `hsla(${r.hue[0]},100%,${endL}%,0)`);
  grad.addColorStop(0.35, `hsla(${r.hue[0]},100%,${midL0}%,${a})`);
  grad.addColorStop(0.65, `hsla(${r.hue[1]},100%,${midL1}%,${a})`);
  grad.addColorStop(1, `hsla(${r.hue[1]},100%,${endL}%,0)`);
  return grad;
}

import { SPR, APP } from "@/lib/nx/sprites";
import { NX_ICONS, NX_ICON_TONE, type NxTone } from "@/lib/nx/icon-paths";

/* ── one dial for icon size, site-wide ────────────────────────────────────
   Every mark in the system is drawn a fixed multiple of the size its call site
   asks for. Applying it HERE rather than editing hundreds of call sites keeps
   the relative sizing intact: an icon that was deliberately smaller than its
   neighbour stays proportionally smaller, it is just bigger in absolute terms.
   Change this one number to retune the whole set.

   Note for anyone adding a primitive: scale exactly ONCE per rendered mark.
   `Plate` draws an `Icon` inside itself, so it scales its own BOX and passes
   the raw size through — scaling in both places would compound to 2.25x. */
export const ICON_SCALE = 1.5;
export const iconPx = (n: number) => Math.round(n * ICON_SCALE);

/**
 * One interface mark.
 *
 * VECTOR FIRST, sprite as the fallback. `lib/nx/icon-paths.ts` carries the set
 * redrawn as 24x24 paths; anything it defines renders as an inline SVG in
 * `currentColor`, and anything it doesn't — the sheet's brand row (linux,
 * docker, postgres…) and the five 3D product renders — still comes off
 * `public/nx/nxicons.webp` exactly as before.
 *
 * Why the switch is here rather than at 137 call sites: the sprite's marks are
 * pre-coloured, so one inside a tinted control renders in the SHEET's colour
 * instead of the control's (a teal shieldcheck on a violet "Admin" chip is the
 * bug that started this). Routing both through one component means every call
 * site gets `currentColor` without being edited, and a name with no vector yet
 * silently keeps working.
 *
 * `size` still means what it always did — ICON_SCALE is applied here for BOTH
 * paths, so a swap is 1:1 and `Plate` (which sizes its box with `iconPx`)
 * needs no change.
 */
export function Icon({
  name, size = 20, className = "", style, strokeWidth = 1.8, tone,
}: {
  name: string; size?: number; className?: string; style?: React.CSSProperties;
  /** Outline weight for vector marks. Ignored by filled marks and the sprite. */
  strokeWidth?: number;
  /**
   * Override the mark's own tone. `"inherit"` hands the colour back to the
   * surrounding text, which is what a mark inside a tinted chip or a solid
   * button needs — though both of those are already handled centrally in
   * globals.css, so passing this is rare.
   */
  tone?: NxTone | "inherit";
}) {
  const s = iconPx(size);
  const vector = NX_ICONS[name];

  if (vector) {
    /* The tone rides as a CLASS, never an inline style. Inline colour would
       beat every context rule, and context has to be able to win: a mark in
       an Admin chip is violet because the CHIP is, not because the sheet drew
       that glyph teal. See `.nx-ico*` in globals.css. */
    const t = tone ?? NX_ICON_TONE[name] ?? "blue";
    return (
      <svg
        aria-hidden
        width={s}
        height={s}
        viewBox="0 0 24 24"
        className={`nx-ico inline-block flex-none ${t === "inherit" ? "" : `nx-ico-${t}`} ${className}`}
        style={style}
        fill={vector.fill ? "currentColor" : "none"}
        stroke={vector.fill ? "none" : "currentColor"}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <path d={vector.d} />
      </svg>
    );
  }

  const [row, col] = SPR[name] ?? SPR.grid;
  return (
    <span
      aria-hidden
      className={"inline-block flex-none bg-no-repeat " + className}
      style={{
        width: s, height: s,
        backgroundImage: "url(/nx/nxicons.webp)",
        backgroundSize: `${20 * s}px ${7 * s}px`,
        backgroundPosition: `-${col * s}px -${row * s}px`,
        ...style,
      }}
    />
  );
}

/** One mark from the 65-app third-party sheet (12 cols x 6 rows). */
export function AppIcon({
  name, size = 32, className = "",
}: { name: string; size?: number; className?: string }) {
  const [row, col] = APP[name] ?? APP.Docker;
  const s = iconPx(size);
  return (
    <span
      aria-hidden
      className={"inline-block flex-none bg-no-repeat " + className}
      style={{
        width: s, height: s,
        backgroundImage: "url(/nx/nxapps.webp)",
        backgroundSize: `${12 * s}px ${6 * s}px`,
        backgroundPosition: `-${col * s}px -${row * s}px`,
      }}
    />
  );
}

/** An icon standing on the card ground.
 *
 * These marks are three-pass neon renders — a bordered, tinted box around one
 * shrinks it and competes with it. So there is no box: the glyph sits at full
 * size on a soft radial glow that reads as light coming off the mark itself.
 */
const GLOW: Record<string, string> = {
  "":  "rgba(47,110,240,0.16)",
  c:   "rgba(0,200,255,0.16)",
  v:   "rgba(150,60,255,0.16)",
  m:   "rgba(235,45,200,0.15)",
};

export function Plate({
  name, size = 52, icon, tone = "", glow = true, className = "",
}: { name: string; size?: number; icon?: number; tone?: "" | "c" | "v" | "m";
     radius?: number; glow?: boolean; className?: string }) {
  const g = icon ?? size;                       // `size` now means the GLYPH size
  // The box matches the SCALED glyph; <Icon> applies the scale itself, so it
  // receives the raw `g` — scaling here as well would compound.
  const box = iconPx(g);
  return (
    <span className={"relative grid flex-none place-items-center " + className}
          style={{ width: box, height: box }}>
      {glow && (
        <span aria-hidden className="pointer-events-none absolute -inset-[30%] rounded-full"
              style={{ background: `radial-gradient(circle, ${GLOW[tone]} 0%, transparent 62%)` }} />
      )}
      <Icon name={name} size={g} className="relative" />
    </span>
  );
}

