// One-off audit script for the ssl/volumes/sites/nxcloud/tools/migrate/projects
// pages. Logs in, visits each path in both dark and light mode, screenshots.
// Delete after use.
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
import { join } from "node:path";

const BASE = process.env.BASE_URL || "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const EMAIL = process.env.NX_EMAIL || "customer@nxeon.local";
const PASS = process.env.NX_PASS || "wGPZqhCbsLdz";
const out = process.argv[2] || "/tmp/audit2";
mkdirSync(out, { recursive: true });

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1100 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();

await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
await page.fill('input[type="email"], input[name="email"]', EMAIL);
await page.fill('input[type="password"], input[name="password"]', PASS);
await Promise.all([
  page.waitForURL((u) => !u.pathname.includes("/login"), { timeout: 45000 }).catch(() => {}),
  page.click("button.btn-primary"),
]);

async function setTheme(theme) {
  await page.evaluate((t) => {
    localStorage.setItem("nx-theme", t);
    document.documentElement.setAttribute("data-theme", t);
  }, theme);
}

async function shot(path, name, { theme = "dark", after } = {}) {
  await page.goto(`${BASE}${path}`, { waitUntil: "networkidle", timeout: 60000 }).catch(async () => {
    await page.waitForTimeout(3000);
  });
  await setTheme(theme);
  await page.waitForTimeout(600);
  // re-apply after nav settles / re-render
  await setTheme(theme);
  await page.waitForTimeout(1200);
  if (after) await after();
  const file = join(out, `${name}.png`);
  await page.screenshot({ path: file, fullPage: true });
  console.log(`${path} [${theme}] ${name} -> ${file}`);
}

const PAGES = [
  ["/dashboard/ssl", "ssl"],
  ["/dashboard/volumes", "volumes"],
  ["/dashboard/sites", "sites"],
  ["/dashboard/nxcloud", "nxcloud"],
  ["/dashboard/tools", "tools"],
  ["/dashboard/migrate", "migrate"],
  ["/dashboard/projects", "projects"],
];

for (const [path, name] of PAGES) {
  await shot(path, `${name}-dark`, { theme: "dark" });
  await shot(path, `${name}-light`, { theme: "light" });
}

// SSL: open "add certificate" modal if present
for (const theme of ["dark", "light"]) {
  await shot("/dashboard/ssl", `ssl-modal-${theme}`, {
    theme,
    after: async () => {
      const btn = page.locator("button, a").filter({ hasText: /request|add certificate|new certificate/i }).first();
      if (await btn.count()) { await btn.click().catch(() => {}); await page.waitForTimeout(700); }
    },
  });
}

// Volumes: open "create volume" modal
for (const theme of ["dark", "light"]) {
  await shot("/dashboard/volumes", `volumes-modal-${theme}`, {
    theme,
    after: async () => {
      const btn = page.locator("button, a").filter({ hasText: /add volume|new volume|create volume/i }).first();
      if (await btn.count()) { await btn.click().catch(() => {}); await page.waitForTimeout(700); }
    },
  });
}

// Sites: open "new site" modal
for (const theme of ["dark", "light"]) {
  await shot("/dashboard/sites", `sites-modal-${theme}`, {
    theme,
    after: async () => {
      const btn = page.locator("button, a").filter({ hasText: /new site|create site/i }).first();
      if (await btn.count()) { await btn.click().catch(() => {}); await page.waitForTimeout(700); }
    },
  });
}

// Migrate: step through the wizard a bit (start -> pick source -> destination)
for (const theme of ["dark", "light"]) {
  await shot("/dashboard/migrate", `migrate-wizard-${theme}`, {
    theme,
    after: async () => {
      const btn = page.locator("button, a").filter({ hasText: /start migration|new migration|migrate a server/i }).first();
      if (await btn.count()) { await btn.click().catch(() => {}); await page.waitForTimeout(900); }
    },
  });
}

await browser.close();

