import { redirect } from "next/navigation";
import { LoginForm } from "@/components/AuthForms";
import { AuthShell } from "@/components/marketing/AuthShell";
import { currentUser } from "@/lib/auth";
import { safeNext } from "@/lib/safe-next";
import { googleOauthConfigured } from "@/lib/google-oauth";
import { discordOauthConfigured } from "@/lib/discord-oauth";
import { roleHome } from "@/lib/portal-home";

/** Friendly copy for the `?error=` codes the Google OAuth routes bounce back. */
const GOOGLE_ERRORS: Record<string, string> = {
  google_unavailable: "Google sign-in isn't set up on this server yet. Use your email and password.",
  google_ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
  google_cancelled: "Google sign-in was cancelled.",
  google_state: "That Google sign-in link expired or didn't match. Please try again.",
  google_unverified: "Your Google email isn't verified, so we can't sign you in with it.",
  google_error: "Couldn't finish signing in with Google. Please try again.",
  account_suspended: "This account is suspended.",
};

/** Friendly copy for the `?error=` codes the Discord OAuth routes bounce back
 *  — same convention as GOOGLE_ERRORS above (a fixed code->message map, never
 *  echoing a server-derived string straight into the query/DOM). */
const DISCORD_ERRORS: Record<string, string> = {
  discord_unavailable: "Discord sign-in isn't set up on this server yet. Use your email and password.",
  discord_ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
  discord_cancelled: "Discord connection cancelled.",
  discord_state: "That Discord sign-in link expired or didn't match. Please try again.",
  discord_unverified_email: "Your Discord account needs a verified email to sign up this way. Verify it on Discord, or create a Nxeon account normally and connect Discord from Settings afterward.",
  discord_email_taken: "An account with this email already exists. Log in normally, then connect Discord from Settings.",
  discord_suspended: "This account is suspended.",
  discord_error: "Couldn't finish signing in with Discord. Please try again.",
};

export default async function LoginPage({
  searchParams,
}: {
  searchParams: Promise<{ next?: string; error?: string }>;
}) {
  // Where the visitor was heading before the login wall. Public CTAs pass this so
  // signing in lands them on what they actually clicked instead of a generic
  // dashboard. Validated by `safeNext` — an unchecked `next` on a login form is an
  // open redirect and therefore a phishing primitive — so it is never trusted,
  // here or in the action.
  const { next, error } = await searchParams;
  const dest = safeNext(next ?? null);
  // Only ever surface a message from our own fixed map — never echo the raw
  // query value into the page.
  const googleError = error ? GOOGLE_ERRORS[error] : undefined;
  const discordError = error ? DISCORD_ERRORS[error] : undefined;
  const discordEnabled = await discordOauthConfigured();

  // Already signed in? Then this page is just a waypoint: send them where they
  // were going. Without this, a public CTA written as `/login?next=/dashboard/x`
  // would strand EXISTING customers on a sign-in form they do not need — trading
  // one dead end for a worse one, since it asks a paying customer to authenticate
  // twice.
  const user = await currentUser();
  if (user) redirect(dest ?? roleHome(user.role));

  return (
    <AuthShell
      heading="Welcome back"
      sub="Sign in to manage your servers and billing."
      bullets={[
        "Instant NVMe VPS provisioning",
        "Real-time metrics and one-click reinstalls",
        "Full root access on every plan",
      ]}
    >
      {/* The VALIDATED destination, never the raw query value: a rejected
          `next` must not be echoed into the DOM at all. It could not cause a
          redirect (the action re-validates), but rendering attacker-supplied
          text into a form for no reason is how the next bug starts. */}
      <LoginForm
        next={dest ?? undefined}
        googleEnabled={googleOauthConfigured()}
        googleError={googleError}
        discordEnabled={discordEnabled}
        discordError={discordError}
      />
    </AuthShell>
  );
}

// blank the name and the email, so a customer told "password must include a
// number" had to retype their whole identity to act on it. Nothing a customer
// typed is thrown away by a rejection.
const [name, setName] = useState("");
const [email, setEmail] = useState("");
return (
  <div className="space-y-4">
    {/* Google/Discord OAuth create the account on first sign-in, so the same
        buttons double as sign-up here. Errors bounced back from the OAuth
        routes surface via googleError/discordError (see app/register/page.tsx). */}
    <ErrorBox error={googleError} />
    <ErrorBox error={discordError} />
    {googleEnabled ? <GoogleButton next={next} /> : null}
    {discordEnabled ? <DiscordButton next={next} /> : null}
    {googleEnabled || discordEnabled ? <OrDivider /> : null}
    <form action={action} className="space-y-4">
      {next ? <input type="hidden" name="next" value={next} /> : null}
      <ErrorBox error={state?.error} />
    <div>
      <label className="label" htmlFor="register-name">Name</label>
      <input
        id="register-name"
        className="input"
        name="name"
        required
        autoComplete="name"
        value={name}
        onChange={(e) => setName(e.target.value)}
      />
    </div>
    <div>
      <label className="label" htmlFor="register-email">Email</label>
      <input
        id="register-email"
        className="input"
        name="email"
        type="email"
        required
        autoComplete="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
      />
    </div>
    <PasswordField id="register-password" />
    <button className="btn-primary w-full" disabled={pending}>
      {pending ? "Creating account…" : "Create account"}
    </button>
    <p className="text-center text-sm text-slate-400">
      Already registered?{" "}
      <Link href="/login" className="text-brand-300 hover:underline">
        Sign in

// clean for the next 30-second window. A no-op on the first challenge.
useEffect(() => {
  if (state?.needs2fa && state?.error) setCode("");
}, [state]);
return (
  <div className="space-y-4">
    {/* An error bounced back from the Google/Discord OAuth routes (see app/login/page.tsx). */}
    <ErrorBox error={googleError} />
    <ErrorBox error={discordError} />
    {googleEnabled ? <GoogleButton next={next} /> : null}
    {discordEnabled ? <DiscordButton next={next} /> : null}
    {googleEnabled || discordEnabled ? <OrDivider /> : null}
    <form action={action} className="space-y-4">
      {/*
      Where the visitor was heading. Re-validated by `safeNext` in
      lib/actions.ts before any redirect — an unvalidated `next` on a login
      form is an open redirect and therefore a phishing primitive, so this
      value is carried, never trusted.
    */}
      {next ? <input type="hidden" name="next" value={next} /> : null}
      <ErrorBox error={state?.error} />
    <div>
      <label className="label" htmlFor="login-email">Email</label>
      <input
        id="login-email"
        className="input"
        name="email"
        type="email"
        required
        autoComplete="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
      />
    </div>
    <PasswordField id="login-password" label="Password" autoComplete="current-password" requireStrong={false} />
    {state?.needs2fa && (
      <div>
        <label className="label" htmlFor="login-2fa-code">2FA code</label>
        {/* Controlled like the rest, so nothing here depends on React's reset
            behaviour. A rejected code is cleared DELIBERATELY below (a TOTP
            code is single-use and time-boxed, so keeping a stale one in the
            box only makes the customer clear it themselves) — the point is
            that the clearing is a decision, not a side effect. */}
        <input
          id="login-2fa-code"
          className="input tracking-[0.3em]"
          name="code"
          inputMode="numeric"
          autoComplete="one-time-code"
          placeholder="123456"
          autoFocus
          value={code}
          onChange={(e) => setCode(e.target.value)}
        />
        <p className="mt-1 text-xs text-slate-500">Enter the 6-digit code from your authenticator app, or a backup code.</p>
      </div>
    )}
    <button className="btn-primary w-full" disabled={pending}>
      {pending ? "Signing in…" : state?.needs2fa ? "Verify & sign in" : "Sign in"}
    </button>
