import { chromium } from "playwright";

const BASE = "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const EMAIL = "customer@nxeon.local";
const PASS = "wGPZqhCbsLdz";

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1100 } });
const page = await ctx.newPage();
page.on("console", (m) => console.log("CONSOLE:", m.text()));
page.on("response", (r) => { if (r.url().includes("/login")) console.log("RESP", r.status(), r.url()); });

await page.goto(`${BASE}/login`, { waitUntil: "networkidle" });
await page.waitForTimeout(1000);
await page.fill('#login-email', EMAIL);
await page.fill('#login-password', PASS);
await page.screenshot({ path: "/tmp/audit2/_debug_before.png" });
await page.click('button.btn-primary');
await page.waitForTimeout(4000);
console.log("URL after click:", page.url());
await page.screenshot({ path: "/tmp/audit2/_debug_after.png" });
await browser.close();

